def median_trapezium(a, b, c, d):
    lengths = [a, b, c, d]
    lengths.sort()
    n = len(lengths)
    if n % 2 == 0:
        median = (lengths[n//2 - 1] + lengths[n//2]) / 2
    else:
        median = lengths[n//2]
    return median

def median_numbers(a, b, c):
