def max_sum_increasing_subseq(arr, i, k, n):
    # Create a table to store results of subproblems
    dp = [[0 for _ in range(n+1)] for _ in range(n+1)]

    # Fill dp table
    for j in range(1, n+1):
        for m in range(1, n+1):
            if j == m:
                dp[j][m] = arr[j-1]
            elif arr[j-1] > arr[m-1]:
                dp[j][m] = max(dp[j-1][m], arr[j-1] + dp[j][m-1])
            else:
                dp[j][m] = dp[j-1][m]

    # Find maximum sum including kth element
    max_sum = 0
    for j in range(i, n+1):
        if j >= k:
            max_sum = max(max_sum, dp[i][j] - arr[i-1])

    return max_sum

