def catalan_number(n):
    if n < 0:
        return "Input should be a non-negative integer."
    elif n == 0:
        return 1
    else:
        catalan_nums = [0 for i in range(n+1)]
        catalan_nums[0] = catalan_nums[1] = 1
        for i in range(2, n+1):
            catalan_nums[i] = 0
