def is_polite(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def sum_of_divisors(num):
        sum = 0
        for i in range(1, num):
            if num % i == 0:
                sum += i
        return sum

    polite_num = 1
    i = 1
    while polite_num < n:
        i += 1
        sum = sum_of_divisors(i)
        if sum == i:
            polite_num += 1
    return polite_num == n

